    for(const auto& [id,encoded]:rows) {
        std::istringstream input(encoded);
        std::string token;
        auto& law=out.modifiers[id];
        while(input>>token) {
            const auto p=token.rfind(':');
            const auto q=p==std::string::npos?
                          std::string::npos:token.rfind(':',p-1);
            if(q==std::string::npos)
                throw std::logic_error("POLITICS_INVALID_REFERENCE_MODIFIER");
            const auto name=token.substr(0,q);
            const auto value=std::stoll(token.substr(q+1,p-q-1));
            const auto kind=token.substr(p+1);
            if(kind!="b"&&kind!="n")
                throw std::logic_error("POLITICS_INVALID_MODIFIER_VALUE");
            if(!law.emplace(name,LawModifier{value,kind=="b"}).second)
                throw std::logic_error("POLITICS_DUPLICATE_LAW_MODIFIER");
        }
    }
